#![forbid(unsafe_code)]
use serde_json::{json,Value};use std::{fs,path::Path};
fn main()->Result<(),Box<dyn std::error::Error>>{let p=Path::new("ejecucion/astra-examen25-conjunto-20261007");let m:Value=serde_json::from_slice(&fs::read(p.join("METRICAS-RUST.json"))?)?;let mut activo=0u64; for d in ["astra-examen25-20261007","astra-examen25-r2-20261007","astra-examen25-r3-20261007"]{let b:Value=serde_json::from_slice(&fs::read(Path::new("ejecucion").join(d).join("RESULTADO-BANCO.json"))?)?;activo+=b["duracion_banco_ms"].as_u64().ok_or("Duración")?;}let rows=m["casos"].as_array().ok_or("Casos")?;assert_eq!(rows.len(),75);assert_eq!(m["conforme"],true);let phases=(0..3).map(|r|{let a=rows.iter().skip(r).step_by(3).collect::<Vec<_>>();json!({"etapa":r,"solicitudes":a.len(),"entrada_tokens":a.iter().map(|v|v["uso"]["entrada_tokens"].as_u64().unwrap()).sum::<u64>(),"salida_tokens":a.iter().map(|v|v["uso"]["salida_tokens"].as_u64().unwrap()).sum::<u64>(),"total_tokens":a.iter().map(|v|v["uso"]["total_tokens"].as_u64().unwrap()).sum::<u64>(),"duracion_ms":a.iter().map(|v|v["duracion_ms"].as_u64().unwrap()).sum::<u64>()})}).collect::<Vec<_>>();let total=|key:&str|rows.iter().map(|v|v[key].as_u64().unwrap()).sum::<u64>();let max=|key:&str|rows.iter().map(|v|v[key].as_u64().unwrap()).max().unwrap();let min=|key:&str|rows.iter().map(|v|v[key].as_u64().unwrap()).min().unwrap();let out=json!({"conforme":true,"etapas":phases,"totales":m["totales"],"duracion_banco_ms":activo,"duracion_solicitud_min_ms":min("duracion_ms"),"duracion_solicitud_max_ms":max("duracion_ms"),"primer_texto_min_ms":min("primer_texto_ms"),"primer_texto_max_ms":max("primer_texto_ms"),"fallos_medicion":total("fallos_medicion"),"intervalo_max_ms":max("intervalo_maximo_ms"),"rss_pico_bytes":max("rss_maximo_bytes"),"cpu_delta_acumulado_ms":total("cpu_delta_ms"),"io_lectura_acumulada_bytes":total("io_lectura_delta_bytes"),"io_escritura_acumulada_bytes":total("io_escritura_delta_bytes"),"tcp_maximo_simultaneo":max("tcp_maximo_simultaneo"),"observaciones_udp":total("observaciones_udp"),"entrada_cache_tokens":rows.iter().map(|v|v["uso"]["entrada_cache_tokens"].as_u64().unwrap()).sum::<u64>(),"razonamiento_tokens":rows.iter().map(|v|v["uso"]["razonamiento_tokens"].as_u64().unwrap()).sum::<u64>(),"autoria_licencia":m["autoria_licencia"]});let bytes=serde_json::to_vec_pretty(&out)?;let f=p.join("RESUMEN-METRICAS-RUST.json");assert!(!f.exists());fs::write(f,&bytes)?;println!("{}",String::from_utf8(bytes)?);Ok(())}
